function setup() {
	createCanvas(1200, 1200);
	background(10, 10, 15);
	pixelDensity(1)
	fill(30)
	rect(0,0,width,height)
	noStroke()

	drawingContext.shadowColor = color(0, 0, 0,30);
	drawingContext.shadowBlur =20;
	drawingContext.shadowOffsetX = 5;
	drawingContext.shadowOffsetY = -5;
