function draw() {
  // === Variant 2: Organic Lissajous Morph ===
  scalePulse = 1.0 + 0.25 * sin(frameCount * 0.03);
  rotAngle = frameCount * 0.015;
  push();
  translate(width/2, height/2);
  rotate(rotAngle);
  scale(scalePulse);
  translate(-width/2, -height/2);

	translate(width/2,height/2)
	let cSpan = 100
	let c1 = (int(frameCount/cSpan))% 5
	let c2 = (int(frameCount/cSpan)+1) % 5
	let ratio = (frameCount/cSpan-int(frameCount/cSpan))
	strokeWeight(2)
	// fill(255,50)
	for(var i=0;i<50;i++){
		push()
		// noFill()
		fill(lerpColor( color(colors[c1]),color(colors[c2]), ratio ))
		rotate(frameCount/(50+10*log(frameCount))+i/20)
		let dd = frameCount/(5+i)+frameCount/5+sin(i)*50
		translate( random(dd/2,dd),0)

		let x = noise(frameCount/50+i/50,5000)*80 + random(50)
		let y = noise(frameCount/50+i/50,10000)*80 + random(50)
		// scale(noise(x,y,i)*2)

		let rr =random(1,8-log(frameCount)/10)
		ellipse(x,y,rr,rr)
		pop()
	}
	// ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 20, 20);

